[
  {
    "id": "90000000-0000-0000-0000-000000000365",
    "title": "The True Ministers of Christ Accredited by the Holy Spirit: A Sermon",
    "description": "The public-domain text of The True Ministers of Christ Accredited by the Holy Spirit: A Sermon by Philip Gell, preserved across 1 original section with extracted Scripture references.",
    "total_days": 12,
    "tags": [
