      "discipleship",
      "wisdom"
    ],
    "cover_image": "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=80",
    "source_url": "https://www.gutenberg.org/ebooks/62001",
